violating:
import { Context, Data, Effect, Layer } from "effect"

export class BlobNotFound extends Data.TaggedError("BlobNotFound")<{
  readonly key: string
}> {}

export class BlobTooLarge extends Data.TaggedError("BlobTooLarge")<{
  readonly size: number
  readonly limit: number
}> {}

export class BlobStore extends Context.Service<BlobStore, {
  readonly read: (
    key: string
  ) => Effect.Effect<Uint8Array, BlobNotFound | BlobTooLarge>
  readonly write: (
    key: string,
    bytes: Uint8Array
  ) => Effect.Effect<void, BlobNotFound | BlobTooLarge>
}>()("storage/BlobStore") {}

const maxBlobSize = 1024 * 1024

export const BlobStoreLive = Layer.sync(BlobStore, () => {
  const blobs = new Map<string, Uint8Array>()

  return {
    read: (key: string) =>
      Effect.suspend(() => {
        const bytes = blobs.get(key)
        return bytes === undefined
          ? Effect.fail(new BlobNotFound({ key }))
          : Effect.succeed(bytes.slice())
      }),
    write: (key: string, bytes: Uint8Array) =>
      Effect.suspend(() => {
        if (bytes.byteLength > maxBlobSize) {
          return Effect.fail(new BlobTooLarge({
            size: bytes.byteLength,
            limit: maxBlobSize
          }))
        }
        return Effect.sync(() => {
          blobs.set(key, bytes.slice())
        })
      })
  }
})

